import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import * as yaml from "js-yaml";
import {
	SOURCE_RECORD_FILENAME,
	SOURCE_RECORD_VERSION,
	compareInstallAction,
	getInstalledState,
	hashExtensionFiles,
	readSourceRecord,
	writeSourceRecord,
} from "../src/filesystem/sourceRecord.js";
import { recordedTrack } from "../src/types/manifest.js";

const FIXTURE_DIR = path.join(__dirname, "fixtures", "q2-record");

const HEADER = [
	"# Generated by Quarto Wizard. Do not edit.",
	"#",
	"# Records where this extension was installed from, and a sha256 of each",
	"# installed file. Before replacing this extension, `q2 add` compares the",
	"# files against these hashes and refuses (without --force) to overwrite",
	"# local changes.",
	"",
].join("\n");

function readFixtureFiles(): Record<string, string> {
	const raw = yaml.load(fs.readFileSync(path.join(FIXTURE_DIR, SOURCE_RECORD_FILENAME), "utf-8")) as {
		files: Record<string, string>;
	};
	return raw.files;
}

function topLevelKeys(content: string): string[] {
	return content
		.split("\n")
		.filter((line) => /^[a-z-]+:/.test(line))
		.map((line) => line.slice(0, line.indexOf(":")));
}

describe("sourceRecord.ts", () => {
	let tempDir: string;

	beforeEach(() => {
		tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "source-record-test-"));
	});

	afterEach(() => {
		fs.rmSync(tempDir, { recursive: true, force: true });
	});

	function writeFile(relativePath: string, content: string | Buffer): void {
		const filePath = path.join(tempDir, relativePath);
		fs.mkdirSync(path.dirname(filePath), { recursive: true });
		fs.writeFileSync(filePath, content);
	}

	describe("the q2 fixture", () => {
		it("hashes the q2 fixture exactly as q2 recorded it", () => {
			const recorded = readFixtureFiles();
			expect(Object.keys(recorded)).toEqual(
				expect.arrayContaining(["assets/pixel.png", "crlf.txt", "café.txt", "_extension.yml", "recorded.lua"]),
			);
			expect(hashExtensionFiles(FIXTURE_DIR)).toEqual(recorded);
		});

		it("reads the q2 fixture record", () => {
			const result = readSourceRecord(FIXTURE_DIR);

			expect(result.status).toBe("ok");
			if (result.status !== "ok") return;
			expect(result.record.version).toBe(1);
			expect(result.record.kind).toBe("local-dir");
			expect(result.record.source.endsWith("q2-record-source")).toBe(true);
			expect(result.record.ref).toBeUndefined();
			expect(result.record.quartoWizard).toBeUndefined();
			expect(result.record.files).toEqual(readFixtureFiles());
		});

		it("reports the q2 fixture as unmodified", () => {
			const state = getInstalledState(FIXTURE_DIR);

			expect(state.kind).toBe("unmodified");
		});
	});

	describe("track", () => {
		const FULL_COMMIT = "3f9c2e1a4b5d6c7e8f90123456789abcdef01234";

		it("writes track, source-type, commit in that order and reads them back", () => {
			writeFile("_extension.yml", "title: Demo\n");

			const written = writeSourceRecord(tempDir, {
				source: "acme/demo",
				kind: "github",
				quartoWizard: { track: "branch", sourceType: "registry", commit: FULL_COMMIT },
			});
			const content = fs.readFileSync(path.join(tempDir, SOURCE_RECORD_FILENAME), "utf-8");

			expect(content).toContain(`quarto-wizard:\n  track: branch\n  source-type: registry\n  commit: ${FULL_COMMIT}\n`);
			expect(readSourceRecord(tempDir)).toEqual({ status: "ok", record: written });
		});

		it("reads an unknown track as absent", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeSourceRecord(tempDir, { source: "acme/demo", kind: "github", quartoWizard: { track: "branch" } });
			const file = path.join(tempDir, SOURCE_RECORD_FILENAME);
			fs.writeFileSync(file, fs.readFileSync(file, "utf-8").replace("track: branch", "track: other"));

			const result = readSourceRecord(tempDir);

			expect(result.status).toBe("ok");
			if (result.status !== "ok") return;
			expect(result.record.quartoWizard).toBeUndefined();
		});

		it("recordedTrack is tag unless a GitHub record says branch", () => {
			expect(recordedTrack(null)).toBe("tag");
			expect(recordedTrack({ kind: "github" })).toBe("tag");
			expect(recordedTrack({ kind: "url", quartoWizard: { track: "branch" } })).toBe("tag");
			expect(recordedTrack({ kind: "github", quartoWizard: { track: "tag" } })).toBe("tag");
			expect(recordedTrack({ kind: "github", quartoWizard: { track: "branch" } })).toBe("branch");
		});
	});

	describe("writeSourceRecord", () => {
		it("writes a record that round-trips and starts with the header", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeFile("filter.lua", "return {}\n");

			const written = writeSourceRecord(tempDir, {
				source: "acme/demo@v1.0.0",
				kind: "github",
				ref: "v1.0.0",
				quartoWizard: { sourceType: "registry", commit: "3f9c2e1" },
			});
			const content = fs.readFileSync(path.join(tempDir, SOURCE_RECORD_FILENAME), "utf-8");
			const read = readSourceRecord(tempDir);

			expect(content.startsWith(HEADER)).toBe(true);
			expect(written.version).toBe(SOURCE_RECORD_VERSION);
			expect(Object.keys(written.files)).toEqual(["_extension.yml", "filter.lua"]);
			expect(read).toEqual({ status: "ok", record: written });
		});

		it("orders keys version, source, kind, ref, files, quarto-wizard", () => {
			writeFile("_extension.yml", "title: Demo\n");

			writeSourceRecord(tempDir, {
				source: "acme/demo@v1.0.0",
				kind: "github",
				ref: "v1.0.0",
				quartoWizard: { sourceType: "registry", commit: "3f9c2e1" },
			});
			const content = fs.readFileSync(path.join(tempDir, SOURCE_RECORD_FILENAME), "utf-8");

			expect(topLevelKeys(content)).toEqual(["version", "source", "kind", "ref", "files", "quarto-wizard"]);
			expect(content).toContain("quarto-wizard:\n  source-type: registry\n  commit: 3f9c2e1\n");
		});

		it("omits ref and quarto-wizard when absent", () => {
			writeFile("_extension.yml", "title: Demo\n");

			const written = writeSourceRecord(tempDir, { source: "acme/demo", kind: "github", quartoWizard: {} });
			const content = fs.readFileSync(path.join(tempDir, SOURCE_RECORD_FILENAME), "utf-8");

			expect(topLevelKeys(content)).toEqual(["version", "source", "kind", "files"]);
			expect(written).not.toHaveProperty("ref");
			expect(written).not.toHaveProperty("quartoWizard");
		});

		it("lists files keys in code point order in the YAML", () => {
			writeFile("b", "b\n");
			writeFile("10", "10\n");
			writeFile("9", "9\n");

			writeSourceRecord(tempDir, { source: "acme/demo", kind: "github" });
			const content = fs.readFileSync(path.join(tempDir, SOURCE_RECORD_FILENAME), "utf-8");
			const keys = content
				.slice(content.indexOf("files:\n"))
				.split("\n")
				.slice(1)
				.filter((line) => line.startsWith("  "))
				.map((line) => yaml.load(line.trim()) as Record<string, string>)
				.map((entry) => Object.keys(entry)[0]);

			expect(keys).toEqual(["10", "9", "b"]);
		});
	});

	describe("readSourceRecord", () => {
		const base = "version: 1\nsource: acme/demo\nkind: github\n";

		it("reads ref: null as no ref and accepts a garbage quarto-wizard block", () => {
			writeFile(SOURCE_RECORD_FILENAME, `${base}ref: null\nfiles: {}\nquarto-wizard: [1, 2]\n`);

			expect(readSourceRecord(tempDir)).toEqual({
				status: "ok",
				record: { version: 1, source: "acme/demo", kind: "github", files: {} },
			});
		});

		it("reports a missing files map or a non-integer version as unreadable", () => {
			writeFile(SOURCE_RECORD_FILENAME, base);
			expect(readSourceRecord(tempDir)).toEqual({ status: "unreadable" });

			writeFile(SOURCE_RECORD_FILENAME, "version: 1.5\nsource: acme/demo\nkind: github\nfiles: {}\n");
			expect(readSourceRecord(tempDir)).toEqual({ status: "unreadable" });
		});

		it("reports a record with a newer schema version as unreadable", () => {
			writeFile(SOURCE_RECORD_FILENAME, "version: 2\nsource: acme/demo\nkind: github\nfiles: {}\n");
			expect(readSourceRecord(tempDir)).toEqual({ status: "unreadable" });
		});
	});

	describe("hashExtensionFiles", () => {
		it("excludes only the top-level record from files", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeFile(SOURCE_RECORD_FILENAME, "version: 1\n");
			writeFile(`nested/${SOURCE_RECORD_FILENAME}`, "version: 1\n");

			const files = hashExtensionFiles(tempDir);

			expect(Object.keys(files)).toEqual([`_extension.yml`, `nested/${SOURCE_RECORD_FILENAME}`]);
			expect(files["_extension.yml"]).toMatch(/^[0-9a-f]{64}$/);
		});

		it("keeps a non-ASCII file name and reports unmodified after a round trip", () => {
			const name = "café.txt";
			writeFile("_extension.yml", "title: Demo\n");
			writeFile(name, "café\n");
			const listed = fs.readdirSync(tempDir).find((entry) => entry.startsWith("caf"));

			const written = writeSourceRecord(tempDir, { source: "./demo", kind: "local-dir" });

			expect(listed).toBeDefined();
			expect(Object.keys(written.files)).toContain(listed);
			expect(getInstalledState(tempDir).kind).toBe("unmodified");
		});

		it("stops a symbolic link loop at depth 32 and names the folder", () => {
			writeFile("_extension.yml", "title: Demo\n");
			fs.symlinkSync(".", path.join(tempDir, "loop"), "dir");

			let message = "";
			try {
				hashExtensionFiles(tempDir);
			} catch (error) {
				message = (error as Error).message;
			}
			const folder = /^(?:Could not read )?(\S+?):? /.exec(message)?.[1] ?? "";
			const depth = path.relative(tempDir, folder).split(path.sep).length;

			expect(message).toContain("a symbolic link may point back into its own tree");
			expect(folder.startsWith(path.join(tempDir, "loop"))).toBe(true);
			expect(depth).toBeGreaterThanOrEqual(30);
			expect(depth).toBeLessThanOrEqual(33);
		});

		it("hashes a file named __proto__", () => {
			writeFile("__proto__", "x\n");

			const files = hashExtensionFiles(tempDir);

			expect(Object.keys(files)).toEqual(["__proto__"]);
			expect(files["__proto__"]).toMatch(/^[0-9a-f]{64}$/);
		});

		it("hashes 32 nested folders and refuses 33", () => {
			const deep32 = path.join(tempDir, ...Array<string>(32).fill("d"));
			fs.mkdirSync(deep32, { recursive: true });
			fs.writeFileSync(path.join(deep32, "file.txt"), "x");

			expect(Object.keys(hashExtensionFiles(tempDir))).toEqual([`${"d/".repeat(32)}file.txt`]);

			fs.mkdirSync(path.join(deep32, "d"));

			expect(() => hashExtensionFiles(tempDir)).toThrow(
				`${path.join(deep32, "d")} is more than 32 directories deep; a symbolic link may point back into its own tree.`,
			);
		});
	});

	describe("getInstalledState", () => {
		it("reports modified, missing and added files", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeFile("filter.lua", "return {}\n");
			writeFile("gone.lua", "return {}\n");
			writeSourceRecord(tempDir, { source: "acme/demo", kind: "github" });

			writeFile("filter.lua", "return { changed = true }\n");
			fs.rmSync(path.join(tempDir, "gone.lua"));
			writeFile("assets/new.css", "body {}\n");

			expect(getInstalledState(tempDir)).toEqual({
				kind: "modified",
				edits: [
					{ path: "assets/new.css", change: "added" },
					{ path: "filter.lua", change: "modified" },
					{ path: "gone.lua", change: "missing" },
				],
			});
		});

		it("reports added files named like Object.prototype members", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeSourceRecord(tempDir, { source: "acme/demo", kind: "github" });

			writeFile("constructor", "x\n");
			writeFile("toString", "x\n");

			expect(getInstalledState(tempDir)).toEqual({
				kind: "modified",
				edits: [
					{ path: "constructor", change: "added" },
					{ path: "toString", change: "added" },
				],
			});
		});

		it("reports an unknown kind as an unreadable install record", () => {
			writeFile("_extension.yml", "title: Demo\n");
			writeFile(SOURCE_RECORD_FILENAME, "version: 1\nsource: acme/demo\nkind: gitlab\nfiles: {}\n");

			expect(readSourceRecord(tempDir)).toEqual({ status: "unreadable" });
			expect(getInstalledState(tempDir)).toEqual({
				kind: "modified",
				edits: [{ path: SOURCE_RECORD_FILENAME, change: "unreadable install record" }],
			});
		});

		it("reports absent and untracked", () => {
			const missing = path.join(tempDir, "missing");
			writeFile("_extension.yml", "title: Demo\n");

			expect(readSourceRecord(tempDir)).toEqual({ status: "absent" });
			expect(getInstalledState(missing)).toEqual({ kind: "absent" });
			expect(getInstalledState(tempDir)).toEqual({ kind: "untracked" });
		});
	});

	describe("compareInstallAction", () => {
		it("compareInstallAction follows q2's matrix", () => {
			expect(compareInstallAction(null, "1.0.0")).toBe("install");
			expect(compareInstallAction("1.2", "1.2.0")).toBe("no-change");
			expect(compareInstallAction("v1", "1.1.0")).toBe("update");
			expect(compareInstallAction("2.0.0", "1.0.0")).toBe("revert");
			expect(compareInstallAction(undefined, "1.0.0")).toBe("update");
			expect(compareInstallAction("dev", "dev")).toBe("update");
		});

		it("compareInstallAction reads prerelease versions", () => {
			expect(compareInstallAction("2.0.0-rc.1", "2.0.0")).toBe("update");
			expect(compareInstallAction("2.0.0", "2.0.0-rc.1")).toBe("revert");
			expect(compareInstallAction("v2.0.0-rc.1", "2.0.0-rc.1")).toBe("no-change");
			expect(compareInstallAction("2.0.0-rc.1", "2.0.0-rc.2")).toBe("update");
		});
	});
});
